def divideDigitArrays(a, b):
    m = len(b)
    rem = []
    q = []
    for d in a:
        if rem or d:
            rem.append(d)
        cnt = 0
        while len(rem) > m or (len(rem) == m and rem >= b):
            borrow = 0
            j = m - 1
            for i in range(len(rem) - 1, len(rem) - m - 1, -1):
                v = rem[i] - b[j] - borrow
                j -= 1
                if v < 0:
                    v += 10
                    borrow = 1
                else:
                    borrow = 0
                rem[i] = v
            if borrow:
                rem[len(rem) - m - 1] -= 1
            k = 0
            while k < len(rem) and rem[k] == 0:
                k += 1
            del rem[:k]
            cnt += 1
        q.append(cnt)
    k = 0
    while k < len(q) - 1 and q[k] == 0:
        k += 1
    return q[k:]
